#![forbid(unsafe_code)]

//! Protobuf determinism and schema compatibility validation tests.
//!
//! These tests ensure that:
//! - Serialization is deterministic (same message → same bytes every time)
//! - Round-trip serialization preserves field values
//! - Edge cases (empty, zero, max values) are handled correctly
//! - Schema changes maintain wire compatibility

use proptest::prelude::*;
use prost::Message;

// Import generated protobuf message types
// (these would be generated by prost from the .proto files)
use andromeda_proto::generated::andromeda::protocol::v1::{
    ErrorEnvelope, FrameEnvelope, ProtocolVersion, RpcBatch, RpcCompletion,
};

use andromeda_proto::generated::andromeda::contract::v1::{
    CatalogProcedureManifestResolutionRequest, CatalogProcedureManifestResolutionResponse,
    ProcedureManifest, ProtocolLayout as GeneratedProtocolLayout, RequiredPermission,
    StructuredObjectHeader, catalog_procedure_manifest_resolution_request,
};
use andromeda_proto::{
    validate_catalog_procedure_manifest_resolution_request,
    validate_catalog_procedure_manifest_resolution_response,
};

#[test]
fn test_protocol_version_deterministic_serialization() {
    let version = ProtocolVersion { major: 1, minor: 0 };

    let bytes1 = version.encode_to_vec();
    let bytes2 = version.encode_to_vec();

    assert_eq!(bytes1, bytes2, "Multiple serializations must be identical");
}

#[test]
fn test_protocol_version_roundtrip() {
    let original = ProtocolVersion { major: 1, minor: 5 };

    let bytes = original.encode_to_vec();
    let decoded =
        ProtocolVersion::decode(bytes.as_slice()).expect("Deserialization should succeed");

    assert_eq!(original, decoded, "Round-trip must preserve all fields");
}

#[test]
fn test_frame_envelope_deterministic_serialization() {
    let envelope = FrameEnvelope {
        protocol_version: Some(ProtocolVersion { major: 1, minor: 0 }),
        contract_hash: vec![42u8; 32],
        catalog_version: 12345,
        request_id: 10,
        session_id: 20,
        tx_id: Some(30),
        payload_kind: 5, // RPC_EXECUTE_REQUEST
        payload: vec![1, 2, 3, 4, 5],
    };

    let bytes1 = envelope.encode_to_vec();
    let bytes2 = envelope.encode_to_vec();
    let bytes3 = envelope.encode_to_vec();

    assert_eq!(bytes1, bytes2, "First and second serializations must match");
    assert_eq!(bytes2, bytes3, "Second and third serializations must match");
}

#[test]
fn test_frame_envelope_edge_cases() {
    // Test: empty contract hash (should not panic, should serialize)
    let envelope_empty_hash = FrameEnvelope {
        protocol_version: Some(ProtocolVersion { major: 1, minor: 0 }),
        contract_hash: vec![],
        catalog_version: 0,
        request_id: 0,
        session_id: 0,
        tx_id: None,
        payload_kind: 1, // HELLO
        payload: vec![],
    };

    let bytes = envelope_empty_hash.encode_to_vec();
    let decoded = FrameEnvelope::decode(bytes.as_slice()).expect("Deserialize with empty hash");

    assert_eq!(envelope_empty_hash, decoded);
}

#[test]
fn test_rpc_batch_deterministic_serialization() {
    let batch = RpcBatch {
        result_name: "users".to_string(),
        batch_index: 1,
        rows_emitted: 100,
        structured_payload: vec![0, 1, 2, 3, 255],
        row_count_exact: Some(1000),
        terminal_batch: false,
    };

    let bytes1 = batch.encode_to_vec();
    let bytes2 = batch.encode_to_vec();

    assert_eq!(bytes1, bytes2, "Batch serializations must be identical");
}

